def update(self, index, iterable, commit=True):
        """
        Updates the index with current data.
        :param index: The search_indexes.Index object
        :param iterable: The queryset
        :param commit: commit to the backend.
        """
        if not index.get_backend().exists():
            index.get_backend().create()

        if not isinstance(iterable, QuerySet):
            iterable = QuerySet(model=iterable.model)
            iterable._iterable_class = iterable._iterable_class.from_queryset(iterable)

        if not index.get_backend().is_alias:
            index.get_backend().refresh()

        if index.get_backend().is_alias:
            index.get_backend().clear()

        for obj in iterable:
            index.get_backend().add(obj)

        if commit:
            index.get_backend().commit()

